<?php
require_once '../config/crud_service.php';require_role('admin');require_once '../includes/crud.php';$error='';$edit=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{save_period($_POST);flash('success','Periode berhasil disimpan; status aktif, kunci dan publikasi diperbarui sesuai pilihan.');redirect('tahun_ajaran.php');}catch(Throwable $e){$error=operation_error($e);$edit=$_POST;}}
elseif(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM tahun_ajaran WHERE id_tahun_ajaran=?');$q->execute([input_id($_GET,'edit')]);$edit=$q->fetch();if(!$edit)not_found();}
$search=input_text($_GET,'q',20,false);$q=db()->prepare('SELECT COUNT(*) FROM tahun_ajaran WHERE tahun_ajaran LIKE ?');$q->execute(['%'.$search.'%']);$total=(int)$q->fetchColumn();[$page,$pages,$offset]=crud_page_bounds($total);$q=db()->prepare("SELECT * FROM tahun_ajaran WHERE tahun_ajaran LIKE ? ORDER BY id_tahun_ajaran DESC LIMIT 20 OFFSET $offset");$q->execute(['%'.$search.'%']);$rows=$q->fetchAll();$page_title='Tahun Ajaran dan Semester';$crud_ui=true;require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php';
?><div class="crud-toolbar"><h2><?=e($page_title)?></h2><a class="btn btn-outline-dark" href="tahun_ajaran.php">Periode baru</a></div><p class="crud-note">Periode nonaktif/terkunci hanya dapat dibaca. Rapor siswa hanya terlihat untuk periode yang dipublikasikan. Publikasikan rapor setelah nilai dan kelengkapannya diperiksa.</p>
<?php if($error):?><div role="alert" class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<form method="post" class="card p-3 mb-4 crud-grid"><?=csrf_field()?><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id_tahun_ajaran" value="<?=e($edit['id_tahun_ajaran']??'')?>"><?php crud_field('tahun_ajaran','Tahun ajaran (2026/2027)',$edit['tahun_ajaran']??'');crud_field('semester','Semester',$edit['semester']??'',['Ganjil'=>'Ganjil','Genap'=>'Genap']);crud_field('status','Status',$edit['status']??'Tidak Aktif',['Aktif'=>'Aktif','Tidak Aktif'=>'Tidak Aktif']);crud_field('dikunci','Kunci transaksi',$edit['dikunci']??'0',['0'=>'Terbuka','1'=>'Terkunci']);crud_field('rapor_diterbitkan','Publikasi rapor',$edit['rapor_diterbitkan']??'0',['0'=>'Belum dipublikasikan','1'=>'Dipublikasikan']);?><button class="btn btn-dark">Simpan Periode</button></form>
<form method="get" class="card p-3 mb-4 crud-grid"><?php crud_field('q','Cari tahun',$search,null,'search',false);?><button class="btn btn-dark">Cari</button></form>
<div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Tahun</th><th>Semester</th><th>Status</th><th>Kunci</th><th>Rapor</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['tahun_ajaran'])?></td><td><?=e($row['semester'])?></td><td><?=e($row['status'])?></td><td><?= $row['dikunci']?'Terkunci':'Terbuka'?></td><td><?= $row['rapor_diterbitkan']?'Dipublikasikan':'Belum dipublikasikan'?></td><td><a class="btn btn-outline-dark" href="?edit=<?=$row['id_tahun_ajaran']?>">Edit</a><form method="post" class="d-inline"><?=csrf_field()?><input type="hidden" name="id_tahun_ajaran" value="<?=$row['id_tahun_ajaran']?>"><button name="action" value="activate" class="btn btn-dark">Aktifkan</button></form></td></tr><?php endforeach;?></tbody></table></div><?php crud_pager($page,$pages,$total);?></div><?php require '../includes/footer.php';
